INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T001', 'HDSAT-RW-M36-T001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Electricity was among the preferred methods for powering early motor vehicles because it was quieter, provided comfort, and ease of operation.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T001', 'A', ARRAY['A']::TEXT[], 'The second sentence limits the advantage described in the first: electric power was preferred, yet its range held it back. ''However'' signals that contrast, while the other transitions would claim a cause, an example, or a similarity the sentence does not supply.', '{"D": "Range limits do not follow as a consequence of quiet operation.", "C": "The sentence is a drawback, not an example of an advantage.", "B": "The two sentences contrast rather than resemble each other."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T002', 'HDSAT-RW-M36-T002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'In the United States alone, zoos are visited by over 181 million people annually.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T002', 'B', ARRAY['B']::TEXT[], 'Popularity and criticism pull in opposite directions, so the second sentence contrasts with the first. ''However'' marks that turn; ''Therefore'' would make the criticism a result of attendance, and the other two choices would imply agreement or illustration.', '{"C": "Criticism does not follow from high attendance.", "A": "The criticism is not an example of popularity.", "D": "The sentences oppose each other rather than align."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T003', 'HDSAT-RW-M36-T003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Currently there are also no plans for building a space colony by any government.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T003', 'A', ARRAY['A']::TEXT[], 'The absence of government plans is set against the many private proposals and advocacy groups, a clear contrast. ''However'' captures that opposition; the other choices would present the proposals as a consequence, an example, or a parallel of the missing plans.', '{"B": "The proposals do not result from the lack of plans.", "C": "The proposals are not an example of government planning.", "D": "The two facts contrast rather than resemble each other."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T004', 'HDSAT-RW-M36-T004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Universal basic income (UBI) is a social welfare proposal in which all members of a given population regularly receive a minimum income in the form of an unconditional transfer payment, i.e., without a means test or need to perform work.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T004', 'D', ARRAY['D']::TEXT[], 'UBI pays everyone unconditionally, while GMI targets only those below a threshold, so the second sentence draws a direct contrast. ''In contrast'' names that difference; the other transitions would wrongly suggest causation, exemplification, or similarity.', '{"B": "The targeted payment is not a result of the universal one.", "A": "GMI is a different design, not an example of UBI.", "C": "The two programs differ in who receives payment."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T005', 'HDSAT-RW-M36-T005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'Homework may improve academic skills among older students, especially lower-achieving students.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T005', 'D', ARRAY['D']::TEXT[], 'The first sentence states a benefit and the second states costs, so the relationship is contrast. ''However'' marks the drawback; ''Therefore'' would treat stress as a consequence of the benefit, and the remaining choices would misstate the relation.', '{"C": "Stress does not follow from improved skills.", "B": "The drawbacks are not an example of the benefit.", "A": "Costs and benefits contrast rather than match."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T006', 'HDSAT-RW-M36-T006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'A WHO-funded study by The Lancet estimates that, during the 50-year period starting in 1974, vaccination prevented 154 million deaths, including 146 million among children under age 5.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T006', 'C', ARRAY['C']::TEXT[], 'A large success is followed by a warning about resurgent disease, so the second sentence qualifies the first rather than extending it. ''However'' signals that qualification; the other choices would imply that the resurgence resulted from the success or resembled it.', '{"D": "Rising cases do not follow from prevented deaths.", "B": "The resurgence is a setback, not an example of success.", "A": "The sentences point in opposite directions."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T007', 'HDSAT-RW-M36-T007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'High-frequency services often prioritize regular headways over exact departure times.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T007', 'B', ARRAY['B']::TEXT[], 'Regular headways are one priority, but the need to coordinate multiple modes complicates that picture, so the second sentence adds a contrasting consideration. The other transitions would wrongly present coordination as a result, an example, or a parallel of headway policy.', '{"A": "Multimodal trips are not caused by regular headways.", "D": "Coordination is a separate concern, not an example of headways.", "C": "The sentences contrast priorities rather than match them."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T008', 'HDSAT-RW-M36-T008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The time spent in each language depends on the model.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T008', 'B', ARRAY['B']::TEXT[], 'The second sentence supplies specific models that illustrate the general claim about varying time in each language. ''For example'' introduces that illustration; ''However'' would wrongly frame it as a contrast, and ''Therefore'' would present it as a consequence.', '{"D": "The models illustrate the claim rather than oppose it.", "A": "The models are examples, not effects of the claim.", "C": "The second sentence is an illustration, not a parallel."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T009', 'HDSAT-RW-M36-T009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'New Orleans jazz began in the early 1910s, combining earlier brass band marches, French quadrilles, biguine, ragtime and blues with collective polyphonic improvisation.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T009', 'C', ARRAY['C']::TEXT[], 'The second sentence corrects the impression that New Orleans was the single origin of jazz, so it contrasts with the first. ''However'' marks that correction; the other choices would treat the correction as a consequence, an example, or a similarity.', '{"B": "The correction does not follow from the origin story.", "A": "It is not an example of a single tradition.", "D": "The sentences oppose a single-origin view."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T010', 'HDSAT-RW-M36-T010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Traditional Japanese haiku consist of three phrases composed of 17 morae (called on in Japanese) in a 5, 7, 5 pattern that include a kireji or "cutting word" and a kigo or seasonal reference.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T010', 'D', ARRAY['D']::TEXT[], 'The second sentence notes that celebrated haiku break the rules just described, which qualifies the definition. ''However'' signals that qualification; the other transitions would wrongly imply that the exceptions follow from the rule or illustrate it.', '{"C": "The exceptions do not result from the definition.", "B": "The poets are exceptions, not examples of the rule.", "A": "The sentence qualifies rather than parallels the definition."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T011', 'HDSAT-RW-M36-T011', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Traditional color theory tends to be more subjective and have artistic applications, while color science tends to be more objective and have functional applications, such as in chemistry, astronomy or color reproduction.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T011', 'D', ARRAY['D']::TEXT[], 'The first sentence separates artistic color theory from objective color science, and the second says the two have in fact intertwined. ''However'' captures that qualification; the other choices would present the intertwining as a result, an example, or a similarity of the split.', '{"B": "The intertwining does not follow from the separation.", "A": "It is not an example of the separation.", "C": "The sentence complicates the contrast rather than matching it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T012', 'HDSAT-RW-M36-T012', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Hard', 'multiple_choice', 'It also offers potential in the treatment of inherited genetic diseases as well as diseases arising from somatic mutations, such as cancer.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T012', 'B', ARRAY['B']::TEXT[], 'The therapeutic promise is set against the controversy over germline modification, a sharp contrast in use. ''However'' marks it; ''Therefore'' would make the controversy a consequence of the promise, and the other choices would misstate the relationship.', '{"D": "Controversy does not follow from therapeutic potential.", "A": "Germline use is a different application, not an example of treatment.", "C": "The sentences contrast promise with objection."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T013', 'HDSAT-RW-M36-T013', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Solar panels use a renewable and clean source of energy, and reduce greenhouse gas emissions compared to hydrocarbon-sourced energy.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T013', 'B', ARRAY['B']::TEXT[], 'The first sentence lists environmental benefits and the second lists practical drawbacks, so the relation is contrast. ''However'' introduces the drawbacks; ''Therefore'' would derive them from the benefits, and the remaining choices would misdescribe the turn.', '{"A": "The drawbacks do not follow from the benefits.", "C": "They are not examples of environmental benefit.", "D": "Benefits and drawbacks contrast."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T014', 'HDSAT-RW-M36-T014', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Hard', 'multiple_choice', 'Due to its energy consumption, desalinating sea water is generally more costly than fresh water from surface water or groundwater, water recycling and water conservation.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T014', 'D', ARRAY['D']::TEXT[], 'Desalination is described as costly, but the second sentence explains why its cheaper alternatives cannot always replace it. ''However'' signals that qualification; the other choices would make the point a consequence, an example, or a parallel of the cost comparison.', '{"A": "The limits on alternatives do not follow from desalination''s cost.", "C": "The point is a qualification, not an example of cost.", "B": "The sentence contrasts cost with availability."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T015', 'HDSAT-RW-M36-T015', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Food deserts are commonly paired with food swamps, which lack grocery stores and instead have convenience stores or fast food.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T015', 'D', ARRAY['D']::TEXT[], 'A food swamp lacks fresh-food access, while a food oasis has it, so the second sentence presents the opposite case. ''In contrast'' marks the opposition; the other choices would imply causation, exemplification, or similarity.', '{"B": "The oasis is not a result of the swamp.", "C": "It is the opposite case, not an example.", "A": "The two areas differ in fresh-food access."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T016', 'HDSAT-RW-M36-T016', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'An individual''s construction of reality, not the objective input, may dictate their behavior in the world.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T016', 'B', ARRAY['B']::TEXT[], 'The second sentence draws a consequence from the claim that subjective construction can drive behavior. ''Thus'' marks that inference; ''However'' would contradict it, and ''Similarly'' or ''For example'' would misdescribe the relation as comparison or illustration.', '{"D": "The consequence does not oppose the premise.", "C": "It is an inference, not a parallel claim.", "A": "The sentence states a result, not an example."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T017', 'HDSAT-RW-M36-T017', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'On Earth, volcanoes are most often found where tectonic plates are diverging or converging, and because most of Earth''s plate boundaries are underwater, most volcanoes are found underwater.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T017', 'B', ARRAY['B']::TEXT[], 'The second sentence names a mid-ocean ridge and the Ring of Fire as specific cases of the boundary types just described. ''For example'' introduces those cases; the other choices would wrongly signal contrast, causation, or similarity.', '{"C": "The cases illustrate the claim rather than oppose it.", "A": "They are examples, not effects of the claim.", "D": "The sentence illustrates rather than parallels."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T018', 'HDSAT-RW-M36-T018', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The most massive exoplanet listed on the NASA Exoplanet Archive is HR 2562 b, about 30 times the mass of Jupiter.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T018', 'C', ARRAY['C']::TEXT[], 'The object is listed as an exoplanet, but its mass may put it outside some definitions of a planet. ''However'' marks that qualification; the other choices would present the doubt as a consequence, an example, or a similarity of the listing.', '{"D": "The classification doubt does not follow from the listing.", "B": "It is not an example of being an exoplanet.", "A": "The sentence qualifies the listing rather than matching it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T019', 'HDSAT-RW-M36-T019', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'With a standard optical telescope, the background space between stars and galaxies is almost completely dark.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T019', 'A', ARRAY['A']::TEXT[], 'What looks dark optically is not empty when observed at radio wavelengths, so the second sentence contrasts with the first. ''However'' signals that contrast; the other choices would wrongly present the glow as a result, an example, or a similar observation.', '{"D": "The radio glow does not follow from optical darkness.", "B": "It is not an example of darkness.", "C": "The sentence contrasts two observations."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T020', 'HDSAT-RW-M36-T020', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Syllabaries use graphemes called syllabograms that represent entire syllables or moras.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T020', 'D', ARRAY['D']::TEXT[], 'Syllabaries encode sound units and logographic systems encode meaning units, so the second sentence presents the opposing design. ''By contrast'' names that difference; the other choices would imply causation, exemplification, or similarity.', '{"A": "Logographic systems are not a result of syllabaries.", "C": "They are a different type, not an example.", "B": "The two systems encode different units."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T021', 'HDSAT-RW-M36-T021', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Tobacco smoke contains nicotine, which is addictive and can cause dependence.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T021', 'C', ARRAY['C']::TEXT[], 'The difficulty of quitting follows from nicotine''s addictive action, so the second sentence states a consequence. ''As a result'' marks that causal link; ''However'' would oppose it, and the other choices would misstate the relation.', '{"B": "Withdrawal difficulty does not contrast with addiction.", "A": "It is a consequence, not an example.", "D": "The sentence states an effect rather than a parallel."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T022', 'HDSAT-RW-M36-T022', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The risk of heart attack in a smoker decreases by 50% after one year of cessation.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T022', 'A', ARRAY['A']::TEXT[], 'Both sentences report a risk falling by half after quitting, so the second parallels the first. ''Similarly'' marks that parallel; ''However'' would wrongly oppose the facts, and ''Therefore'' or ''For example'' would misdescribe the relation.', '{"B": "The two findings agree rather than conflict.", "D": "The second is a parallel finding, not a result.", "C": "It is a comparable fact, not an illustration."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T023', 'HDSAT-RW-M36-T023', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Hard', 'multiple_choice', 'Health is a basic human right and human need, and all human rights are interconnected.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T023', 'B', ARRAY['B']::TEXT[], 'The conclusion that health must be discussed with other rights follows from the premises that health is a right and rights are interconnected. ''Thus'' marks that inference; the other choices would misstate it as contrast, illustration, or mere similarity.', '{"D": "The conclusion does not oppose the premises.", "A": "It is an inference, not an example.", "C": "The sentence draws a conclusion rather than a parallel."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M36-T024', 'HDSAT-RW-M36-T024', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Using human characteristics as descriptors of machines in metaphorical ways was already practiced by Alan Turing with terms such as "memory", "search" and "stimulus".
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M36-T024', 'A', ARRAY['A']::TEXT[], 'The second sentence defines a heuristic as something looser than a rigorously specified procedure, so it contrasts with the first. ''In contrast'' marks the difference; the other choices would imply causation, exemplification, or similarity.', '{"B": "The heuristic definition is not a result of Turing''s usage.", "C": "It is a different concept, not an example.", "D": "The sentence contrasts two approaches."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
